{
  "rewrite_sql": "-- Set aggressive timeouts to fail fast instead of queuing behind traffic
SET lock_timeout = '2s';
SET statement_timeout = '30s';

-- Backfill orders.status = 'pending' where NULL, in batches
-- to avoid holding row locks for too long
DO $$
DECLARE
  batch_size INT := 1000;
  updated INT;
BEGIN
  LOOP
    UPDATE orders 
    SET status = 'pending'
    WHERE id IN (
      SELECT id 
      FROM orders 
      WHERE status IS NULL 
      LIMIT batch_size
    );

    GET DIAGNOSTICS updated = ROW_COUNT;
    EXIT WHEN updated = 0;

    RAISE NOTICE 'Backfilled status for % orders', updated;
    PERFORM pg_sleep(0.05);
  END LOOP;
END $$;

-- Backfill order_items.quantity = 1 for all rows, in batches by ID range
-- to avoid holding row locks for too long
DO $$
DECLARE
  batch_size INT := 1000;
  min_id INT;
  max_id INT;
  current_min INT;
  updated INT;
BEGIN
  SELECT MIN(id), MAX(id) INTO min_id, max_id FROM order_items;

  IF min_id IS NULL THEN
    RAISE NOTICE 'No order_items to backfill';
    RETURN;
  END IF;

  current_min := min_id;

  WHILE current_min <= max_id LOOP
    UPDATE order_items 
    SET quantity = 1
    WHERE id >= current_min AND id < current_min + batch_size;

    GET DIAGNOSTICS updated = ROW_COUNT;

    IF updated > 0 THEN
      RAISE NOTICE 'Backfilled quantity for % order_items (id: % to %)', 
        updated, current_min, current_min + batch_size - 1;
    END IF;

    current_min := current_min + batch_size;
    PERFORM pg_sleep(0.05);
  END LOOP;
END $$;",
  "notes": "Rewrote both UPDATEs to process in small batches (1000 rows) instead of all at once. Added lock_timeout (2s) and statement_timeout (30s) to fail fast instead of queuing indefinitely behind production traffic. Added 50ms sleeps between batches to reduce lock contention. Added NOTICE logging for observability during migration. The orders backfill processes WHERE status IS NULL in batches; the order_items backfill processes all rows by ID range. Both are now safe for large tables in production.",
  "deferred": false
}
